{
  "findings": [
    {
      "ref": "[R98]",
      "area": "age_gating",
      "claim": "A parent reports that skins revert to Steve after closing the app.",
      "stance": "risk",
      "quote": "I noticed all my skins are Steve. I always import skins and whenever I close the app they turn back into Steve!"
    },
    {
      "ref": "[R111]",
      "area": "contact",
      "claim": "A parent reports Microsoft gives the family manager error joining other people or adding friends.",
      "stance": "risk",
      "quote": "I often find vanilla Minecraft to be boring, but when I try to use mods that were purchased on Minecraft marketplace, there is a major flaw that makes me walk through blocks and drown. It also upsets me that I can’t play with my mom because Microsoft keeps giving her the error that she cannot join other people or add friends, even though she is the family manager, and all her settings are just like mine."
    },
    {
      "ref": "[R112]",
      "area": "contact",
      "claim": "A parent reports mobile players on the same connection cannot join each other's games.",
      "stance": "risk",
      "quote": "Me and my friends always try to play together, but if you’re on the same connection on mobile as another player or the host, you cannot join their game on mobile please fix this glitch."
    },
    {
      "ref": "[R126]",
      "area": "money",
      "claim": "A parent reports being charged three times for the same add-on and having issues buying coins.",
      "stance": "risk",
      "quote": "Attempted to buy add ons like I have in the past, it wasn’t working and after the third attempt for the same product, I was charged for buying the same add on 3 times. The next day I attempted to just buy coins, only one attempt. Says it went through and never got that product either."
    },
    {
      "ref": "[R123]",
      "area": "money",
      "claim": "A parent reports an add-on purchase did not refund mine coins after deletion.",
      "stance": "risk",
      "quote": "I bought this morph add-on. I really don’t like it so I deleted it and it didn’t give me my mine coins back"
    },
    {
      "ref": "[R144]",
      "area": "contact",
      "claim": "A parent reports parental controls cannot be turned off.",
      "stance": "risk",
      "quote": "When my parents try to turn off parental controls it won't work. We tried everything but it refused to change."
    },
    {
      "ref": "[R146]",
      "area": "contact",
      "claim": "A parent reports being unable to join OneBlockOnline.",
      "stance": "risk",
      "quote": "I can’t get onto OneBlockOnline. Can you please fix this issue?"
    },
    {
      "ref": "[R147]",
      "area": "money",
      "claim": "A parent reports a monthly charge not clearly stated up front.",
      "stance": "risk",
      "quote": "I think it’s pretty scummy to not state up front that this is a monthly charge, not a one-and-done payment."
    },
    {
      "ref": "[R157]",
      "area": "data",
      "claim": "A parent reports skin reset to default, losing purchased customizations.",
      "stance": "risk",
      "quote": "YOU RESET MY BEUTIFULL SKIN INTO STINKY DEFAULT SKINS!!!"
    },
    {
      "ref": "[R159]",
      "area": "money",
      "claim": "A parent reports coal items disappearing, possibly related to in-game economy.",
      "stance": "neutral",
      "quote": "When I come to play again after a few hours, I notice that all my coal disappears from my items."
    },
    {
      "ref": "[R162]",
      "area": "contact",
      "claim": "A parent reports being unable to sign in due to locked account and unusual activity warnings.",
      "stance": "risk",
      "quote": "Gosh Minecraft NEVER have I EVER been so MAD in my life! I use to play Minecraft on my ps4 BACK THEN! And now I downloaded it on my phone after thinking of it, but as I put my email in it says account has been locked! So I used my mother’s email and it work but it was talking about some unusual activity"
    }
  ]
}
